// SEO Enhancements Script - Minimal Version (No hardcoded SEO content)
// Version: 2.0.0
// For: Free Templates page
// NOTE: Title/description management removed - use Webflow CMS

(function(){'use strict';var SEO_CONFIG={DEBUG:true,SUBCATEGORY_NOINDEX:true,CANONICAL_SELF_REFERENCE:true,SELECTORS:{titleBreadcrumb:'#title-breadcrumb',breadcrumbContainer:'.mp-breadcrumbs',dynamicBreadcrumb:'[data-dynamic-breadcrumb="true"]:not(.mp-breadcrumb-divider)',dynamicDivider:'[data-dynamic-breadcrumb="true"].mp-breadcrumb-divider',categoryTitle:'.h3',categoryDescription:'.u-text-gray600'}};function log(message,data){if(SEO_CONFIG.DEBUG){console.log('[SEO-Enhancements-Minimal]',message,data||'')}}function getUrlParameter(name){try{var url=new URL(window.location.href);return url.searchParams.get(name)}catch(e){var regex=new RegExp('[?&]'+name+'(=([^&#]*)|&|#|$)');var results=regex.exec(window.location.href);if(!results)return null;if(!results[2])return'';return decodeURIComponent(results[2].replace(/\+/g,' '))}}function formatCategoryName(urlParam){if(!urlParam)return'';return urlParam.split('-').map(word=>word.charAt(0).toUpperCase()+word.slice(1)).join(' & ')}function getCurrentPageType(){var category=getUrlParameter('category');var subcategory=getUrlParameter('subcategory');if(subcategory){return{type:'subcategory',category:category,subcategory:subcategory}}else if(category){return{type:'category',category:category}}else{return{type:'base'}}}function updateCanonicalUrl(){if(!SEO_CONFIG.CANONICAL_SELF_REFERENCE)return;var canonicalLink=document.querySelector('link[rel="canonical"]');if(!canonicalLink){canonicalLink=document.createElement('link');canonicalLink.setAttribute('rel','canonical');document.head.appendChild(canonicalLink)}var currentUrl=window.location.href;canonicalLink.setAttribute('href',currentUrl);log('Updated canonical URL to self-reference:',currentUrl)}function addNoindexForSubcategories(){if(!SEO_CONFIG.SUBCATEGORY_NOINDEX)return;var pageType=getCurrentPageType();if(pageType.type==='subcategory'){var robotsMeta=document.querySelector('meta[name="robots"]');if(!robotsMeta){robotsMeta=document.createElement('meta');robotsMeta.setAttribute('name','robots');document.head.appendChild(robotsMeta)}robotsMeta.setAttribute('content','noindex, follow');log('Added noindex for subcategory page:',pageType.subcategory)}}function updateVisibleElements(){var pageType=getCurrentPageType();var elements={categoryTitle:document.querySelector(SEO_CONFIG.SELECTORS.categoryTitle),categoryDescription:document.querySelector(SEO_CONFIG.SELECTORS.categoryDescription)};log('Current page type:',pageType);log('Found elements:',Object.keys(elements).filter(key=>elements[key]).join(', '));if(pageType.type==='category'){log('Category page detected - showing description');if(elements.categoryDescription){elements.categoryDescription.style.display='block';log('✅ Showing description for category')}}else if(pageType.type==='subcategory'){log('Subcategory page detected - hiding description');if(elements.categoryDescription){elements.categoryDescription.style.display='none';log('✅ Hidden description for subcategory')}}else{log('Base page detected - showing default description');if(elements.categoryDescription){elements.categoryDescription.style.display='block';log('✅ Showing default description')}}}function handleUrlChange(){log('URL change detected, updating SEO elements');updateCanonicalUrl();addNoindexForSubcategories();updateVisibleElements()}function init(){log('SEO Enhancements (Minimal) initializing...');handleUrlChange();document.addEventListener('categoryFilterUpdated',function(){setTimeout(handleUrlChange,100)});window.addEventListener('popstate',function(){setTimeout(handleUrlChange,100)});log('SEO Enhancements (Minimal) initialized successfully')}window.SEOEnhancements={updateSEO:handleUrlChange,config:SEO_CONFIG,debug:function(enabled){SEO_CONFIG.DEBUG=enabled;log('Debug mode',enabled?'enabled':'disabled')}};log('🚀 SEO Enhancements v2.0 (Minimal) starting...');if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init)}else{init()}})();
